{
  "hypotheses": [
    {
      "id": "H1",
      "mechanism": "The controller's gait frequency (1.555 Hz) is far above the body's natural pendulum frequency (0.479 Hz), giving a controller_freq_ratio of 3.244. This forces overly rapid stepping (step_freq_hz=3.844) that prevents effective force generation and leads to consistent forward falls (forward_fall_frac=1.0, fall_time_s=3.283).",
      "evidence": [
        "baseline.controller_freq_ratio",
        "baseline.pendulum_freq_hz",
        "baseline.controller_freq_hz",
        "baseline.step_freq_hz",
        "baseline.forward_fall_frac",
        "baseline.fall_time_s"
      ],
      "competing": ["The high frequency might be a symptom of incorrect feedback gains causing oscillation rather than a timing parameter error."]
    },
    {
      "id": "H2",
      "mechanism": "The body's torque authority (tau_ratio=0.36) is much lower than the reference body (0.995), limiting the controller's ability to generate necessary joint torques for balance. Torque saturation is zero and peak torques are well below limits (hip 0.68, knee 0.81, ankle 0.70), suggesting the controller may be torque-limited.",
      "evidence": [
        "creature.features.tau_ratio",
        "creature.reference.features.tau_ratio",
        "baseline.torque_authority",
        "baseline.saturation_frac",
        "baseline.peak_tau_over_limit_hip",
        "baseline.peak_tau_over_limit_knee",
        "baseline.peak_tau_over_limit_ankle"
      ],
      "competing": ["The controller may not be demanding enough torque due to gain mismatches; increasing torque limit may not help if demands are low."]
    },
    {
      "id": "H3",
      "mechanism": "The current R2 transfer controller does not account for the large differences in leg length (L=1.081 vs 0.6), torque authority (0.36 vs 0.995), and foot-to-leg ratio (0.115 vs 0.267). A controller transferred by dynamic similarity (scaling frequency, gains, and ramp by leg length and mass) would better match the body's dynamics.",
      "evidence": [
        "creature.features.L",
        "creature.reference.features.L",
        "creature.features.tau_ratio",
        "creature.reference.features.tau_ratio",
        "creature.features.foot_to_leg",
        "creature.reference.features.foot_to_leg"
      ],
      "competing": ["The current controller might be better if the transfer method was different; dynamic similarity might not account for all differences."]
    }
  ],
  "probes": [
    {
      "probe_id": "similarity",
      "hypothesis": "H3",
      "expect": "improves"
    },
    {
      "probe_id": "opt_timing",
      "hypothesis": "H1",
      "expect": "improves"
    },
    {
      "probe_id": "torque_x1_5",
      "hypothesis": "H2",
      "expect": "improves"
    }
  ]
}

